#!/usr/bin/env python3
"""A generated root edited or regenerated by hand is detected and reported, naming its Secret (#309 C).

    hack/validate-credential-drift.py [repo-root]

External Secrets Operator v2.14.0 regenerates a generated root the moment its Secret's data stops matching its data-hash
annotation (pkg/controllers/externalsecret/externalsecret_controller.go:370: a refresh is skipped only when
`!shouldRefresh(es) && isSecretValid(secret, es)`, and isSecretValid is false on a data-hash mismatch under
creationPolicy Owner, whatever the refresh policy; only Orphan is always valid). So editing a root silently rotates it
to a fresh random value. The umbrella cannot recompute ESO's data-hash (runtime/esutils ObjectHash is SHA3-224 of Go's
%+v rendering; sprig has no SHA3), so it latches its own sha256 of each root's data
(osh.credentialDrift, templates/credential-drift.yaml) and reports a change until acknowledged with the sha the
report shows (credentialDrift.acknowledge).

  1. THE LATCH. templates/credential-drift.yaml is rendered with stand-ins for osh.lookupSecret and
     osh.lookupConfigMap (helm template's lookup returns nothing, so an offline render would show no root at all):
       a. no root Secret: no state for it, no drift;
       b. a root, no previous state: baselined with its sha256, no drift;
       c. previous state equal to the root: unchanged, no drift;
       d. the root changed, not acknowledged: a ConfigMap openstack-credential-drift-<Secret>, and the state keeps the
          OLD baseline (so the drift stays reported on the next render);
       e. acknowledged with the current sha (credentialDrift.acknowledge.<Secret>): re-baselined, no drift;
       e2. acknowledged with a stale sha: still reported (an operator acknowledges exactly what they saw);
       f. a provided root (Ceph) changed: never latched (its owner rotates it by design, #308).
     The expected sha256 is computed here, independently, from the stand-in Secret's data.
  2. THE REPORT. blueprints/openstack/compositiondefinition.yaml has one statusDataTemplate entry for credentialDrift;
     its jq is EXECUTED (jq binary): drift ConfigMaps present -> exactly their Secrets' names; none -> [] (a stale list
     is replaced); other ConfigMaps ignored.

Fails when helm, jq or PyYAML is missing, and when a case renders nothing to check.
"""
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

try:
    import yaml
except ImportError:
    print("FAILED MEASUREMENT: PyYAML unavailable, so nothing was checked")
    sys.exit(2)

ROOT = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else ".")
UMBRELLA = os.path.join(ROOT, "blueprints", "openstack", "chart")
CD = os.path.join(ROOT, "blueprints", "openstack", "compositiondefinition.yaml")
TOOLKIT = os.path.join(ROOT, "charts", "helm-toolkit")
failures = []
for tool in ("helm", "jq"):
    if shutil.which(tool) is None:
        print("FAILED MEASUREMENT: %s not on PATH, so nothing was checked" % tool)
        sys.exit(2)


def fail(m):
    failures.append(m)


def stage(tmp):
    w = os.path.join(tmp, "umbrella")
    shutil.copytree(UMBRELLA, w)
    cy = os.path.join(w, "Chart.yaml")
    txt = open(cy).read()
    open(cy, "w").write(txt.replace("CHART_VERSION", "0.0.0-gate"))
    if os.path.isdir(TOOLKIT):
        os.makedirs(os.path.join(w, "charts"), exist_ok=True)
        shutil.copytree(TOOLKIT, os.path.join(w, "charts", "helm-toolkit"))
    hp = os.path.join(w, "templates", "_helpers.tpl")
    h = open(hp).read()
    for name, key in (("osh.lookupSecret", "gateSecrets"), ("osh.lookupConfigMap", "gateConfigMaps")):
        rx = re.compile(r'(\{\{- define "%s" -\}\}).*?(\{\{- end -\}\})' % re.escape(name), re.S)
        if not rx.search(h):
            print("FAILED MEASUREMENT: _helpers.tpl defines no %s, so it cannot be stood in for" % name)
            sys.exit(2)
        h = rx.sub(lambda m: m.group(1) + "\n{{- index ((index . 0).Values.%s | default dict) (index . 1) | default dict "
                   "| toJson -}}\n" % key + m.group(2), h, count=1)
    open(hp, "w").write(h)
    return w


def render(w, vals):
    with tempfile.NamedTemporaryFile("w", suffix=".yaml", delete=False) as f:
        yaml.safe_dump(vals, f)
    try:
        r = subprocess.run(["helm", "template", "openstack-gate", w, "-n", "openstack", "--kube-version", "1.36.0",
                            "--show-only", "templates/credential-drift.yaml", "-f", f.name],
                           capture_output=True, text=True)
    finally:
        os.unlink(f.name)
    if r.returncode != 0 and "could not find template" in r.stderr:
        return {}, []   # nothing rendered at all
    if r.returncode != 0:
        fail("1: templates/credential-drift.yaml does not render: %s" % r.stderr.strip()[:300])
        return None, None
    docs = [d for d in yaml.safe_load_all(r.stdout) if d]
    state = next((d.get("data") or {} for d in docs if d["metadata"]["name"] == "openstack-credential-generations"), {})
    drift = sorted(d["data"]["secret"] for d in docs if d["metadata"]["name"].startswith("openstack-credential-drift-"))
    return state, drift


def sha(data):
    # helm's toJson of the Secret's data map: keys sorted, no spaces (Go's encoding/json).
    return hashlib.sha256(json.dumps(data, separators=(",", ":"), sort_keys=True).encode()).hexdigest()


def part1(tmp):
    uv = yaml.safe_load(open(os.path.join(UMBRELLA, "values.yaml")))
    items = (uv.get("credentials") or {}).get("items") or []
    gen = next((i for i in items if i["id"] == "oslo-messaging-heat"), None)
    prov = next((i for i in items if i.get("source") == "provided"), None)
    if not gen or not prov:
        fail("1: credentials.items has no oslo-messaging-heat or no provided item: the cases have nothing to latch")
        return 0
    w = stage(tmp)
    old, new = {"password": "b2xk"}, {"password": "bmV3"}
    s_old, s_new = sha(old), sha(new)
    gs = lambda d: {gen["secret"]: {"data": d}}
    cm = lambda v: {"openstack-credential-generations": {"data": {gen["id"]: v}}}
    cases = [
        ("a. no root Secret", {}, None, []),
        ("b. a root, no previous state", {"gateSecrets": gs(old)}, s_old, []),
        ("c. unchanged", {"gateSecrets": gs(old), "gateConfigMaps": cm(s_old)}, s_old, []),
        ("d. changed, not acknowledged", {"gateSecrets": gs(new), "gateConfigMaps": cm(s_old)}, s_old, [gen["secret"]]),
        ("e. changed, acknowledged with the current sha", {"gateSecrets": gs(new), "gateConfigMaps": cm(s_old),
                                                           "credentialDrift": {"acknowledge": {gen["secret"]: s_new}}},
         s_new, []),
        ("e2. changed, acknowledged with a stale sha (what the operator saw is no longer current)",
         {"gateSecrets": gs(new), "gateConfigMaps": cm(s_old),
          "credentialDrift": {"acknowledge": {gen["secret"]: s_old}}}, s_old, [gen["secret"]]),
        ("f. a provided root changed", {"gateSecrets": {prov["secret"]: {"data": new}},
                                        "gateConfigMaps": {"openstack-credential-generations": {"data": {
                                            prov["id"]: s_old}}}}, None, []),
    ]
    n = 0
    for label, vals, want_state, want_drift in cases:
        state, drift = render(w, vals)
        if state is None:
            continue
        got = state.get(gen["id"])
        if got != want_state:
            fail("1: %s: the latched state for %s is %r, want %r" % (label, gen["id"], got, want_state))
        elif label.startswith("f.") and prov["id"] in state:
            fail("1: %s: the provided root %s is latched; its owner rotates it by design (#308)" % (label, prov["id"]))
        elif drift != want_drift:
            fail("1: %s: drift reported for %s, want %s" % (label, drift, want_drift))
        else:
            n += 1
    return n


def part2():
    cd = yaml.safe_load(open(CD))
    ents = [e for e in (cd.get("spec") or {}).get("statusDataTemplate") or [] if e.get("forPath") == "credentialDrift"]
    if len(ents) != 1 or not ents[0].get("preserveUnknownFields"):
        fail("2: the CompositionDefinition needs exactly one statusDataTemplate entry for credentialDrift, "
             "preserveUnknownFields")
        return 0
    m = re.match(r"^\$\{(.*)\}$", ents[0].get("expression", "").strip(), re.S)
    if not m:
        fail("2: the credentialDrift expression is not a ${ jq } program")
        return 0
    expr = m.group(1)
    cmv = lambda n: {"resource": "configmaps", "name": n}
    cases = [
        ([cmv("openstack-credential-drift-openstack-credential-oslo-messaging-heat"), cmv("openstack-install-pending"),
          {"resource": "secrets", "name": "openstack-credential-drift-x"}],
         ["openstack-credential-oslo-messaging-heat"]),
        ([cmv("openstack-install-pending")], []),
        (None, []),
    ]
    n = 0
    for managed, want in cases:
        doc = {"status": {"managed": managed}} if managed is not None else {"status": {}}
        r = subprocess.run(["jq", "-c", expr], input=json.dumps(doc), capture_output=True, text=True)
        got = json.loads(r.stdout) if r.returncode == 0 and r.stdout.strip() else "<jq error: %s>" % r.stderr.strip()[:200]
        if got != want:
            fail("2: credentialDrift over %s is %s, want %s" % (managed, got, want))
        else:
            n += 1
    return n


def main():
    with tempfile.TemporaryDirectory() as tmp:
        n1 = part1(tmp)
    n2 = part2()
    if not n1:
        fail("part 1 checked nothing")
    if not n2:
        fail("part 2 checked nothing")
    if failures:
        for f in failures:
            print("FAIL: " + f)
        sys.exit(1)
    print("OK: a hand-edited generated root is latched and reported: %d latch case(s) (lookup stood in) and %d status "
          "projection case(s) (jq executed)" % (n1, n2))


main()
